function searchSystems(data, query, limit = 12) {
	const q = query.trim().toLowerCase();
	if (!q) return [];
	const scored = [];
	for (const s of data.systems) {
		const name = s.name.toLowerCase();
		let n = -1;
		if (name === q) n = 0;
		else if (name.startsWith(q)) n = 1;
		else if (name.includes(q)) n = 2;
		else if (s.sector.toLowerCase().includes(q) || s.grid.toLowerCase() === q || s.region.toLowerCase().includes(q)) n = 3;
		if (n >= 0) scored.push({
			s,
			n
		});
	}
	scored.sort((a, b) => a.n - b.n || a.s.name.localeCompare(b.s.name));
	return scored.slice(0, limit).map((x) => x.s);
}
